import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"37、【家人】 離下巽上","description":"周易闡真 - 37、【家人】 離下巽上","frontmatter":{"title":"37、【家人】 離下巽上","description":"周易闡真 - 37、【家人】 離下巽上"},"headers":[],"relativePath":"classics/chanzhen/038.md","filePath":"classics/chanzhen/038.md"}'),s={name:"classics/chanzhen/038.md"};function n(c,a,i,o,l,h){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：家人，女正位乎內，男正位乎外。男女正，天地之大義也。家人有嚴君焉，父母之謂也。父父，子子，兄兄，弟弟，夫夫，婦婦，而家道正。正家而天下定矣。</p></blockquote><h1 id="_37、【家人】-離下巽上" tabindex="-1">37、【家人】 離下巽上 <a class="header-anchor" href="#_37、【家人】-離下巽上" aria-label="Permalink to “37、【家人】 離下巽上”">​</a></h1><p>初九：閒有家，悔亡。</p><p>六二：無攸遂，在中饋，貞吉。</p><p>九三：家人嗃嗃，悔厲吉。婦子嘻嘻，終吝。</p><p>六四：富家，大吉。</p><p>九五：王假有家，勿恤，吉。</p><p>上九：有孚威如，終吉。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：風自火出，家人。君子以言有物而行有恆。</p><p>家人者，一家之人也。上巽風，下離火，是火在內，風在外，風自火出，火燃而風自生，風火一家，家人之象也。</p><p>君子有見於此，知風火一處，風生必本於火，火燃而風自生；人我同居，成物必本於己，己正而人自化。以是言不空言，言必有物；行不妄行，行必有恆。謹言慎行，則同居者皆亦言物行恆，而與我為一家之人矣。家人不僅是同家之人，凡與我同居同事者皆是。物，如事也；恆，有終也。言有物者，因事而言；有指有證，言必合理。行有恆者，有終之行；真履實踐，行必有成。以物而言，以恆而行，言行無虧，內不失己，外不傷人，則同居同事者，俱默相感化，亦如火燃而風自生矣。夫言者，心之聲；行者，身之律。修道者，有物而言，有恆而行，則心正身修，性命有寓，方且上下與天地同流，而以天地為一家，豈第家人而矣哉！</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>饋，音匱。嗃，音郝。嘻，音希。</p><p>家人者，家中有人，治內之道。卦德上巽入，下離明，明則可以巽行其道，巽則能以漸通其明，巽明相需，如以風吹火，火隨風生，有治家之道，故謂家人。此煉己持心、迴光返照之卦，承上晉卦而來。晉者，明由順生，進火用明之功。進火用明，須先明內，明內者煉己也。煉己者，煉我家之陰耳。我家之陰為何陰?人心是也。人身精、神、魂、魄、意，皆屬陰，聽命於人心，人心靜而五者皆靜，人心動而五者皆動，煉己即煉此人心耳。煉去人心，道心自現，道心現而心明，則精、神、魂、魄、意，皆化而為護法神矣。</p><p>人之身，如家也；人之精、神、魂、魄、意，如一家之人也。煉人心而生道心，精、神、魂、魄、意，各安其位，各伺其事，喜、怒、哀、樂，皆和而中節，如一家治也。取象利女貞，女以守貞為貴，煉己如女之守貞不字，則我家之真陰現象。真陰現象，則心虛靈不昧，外物不得而入，可以循序漸進，以求他家之陽，無有不利者。卦體二虛於下，五實於上。虛心即能以實腹，利女貞，正所以致虛守靜，以為成家立業計耳。故修道者，戒慎恐懼，於不睹不聞之內，不使有一毫陰氣潛藏於方寸之中也。</p><p>初九，在家人之初，剛於煉己，如閒有家也。有己即能防閒剋制，方寸之中，空空洞洞，內念不生，外不入，本有悔而悔可亡。此煉已於有己之初者也。</p><p>六二，柔而中正，返觀內照，心清意靜，不專遂於外，而謹慎於內，以靜制動，以一御紛，外物不納，客氣難入，如婦人在中饋而居貞，未有不得吉者。此煉己而用柔道者也。</p><p>九三，煉己功勤，雜念不生，如家人嗃嗃，悔厲驚懼，不敢為惡，自然得吉。否則有念不去，姑息養奸，恣情縱欲，如婦子嘻嘻，略無家法，焉能到得無己之時?如此修道，終不成道，取吝而已。此煉己當用剛道者也。</p><p>六四，以柔求剛，借剛濟柔，不即不離，漸次導引。虛心即能實腹，富有日新，方且積法財、聚天寶，其吉之大，不僅無己而已。此煉己柔而用剛者也。</p><p>九五，陽剛得中，心正而身修，如王者假家施治，而天下自平，其吉出於自然，非有勉強，何憂恤之有?此煉己而剛柔如一者也。</p><p>上九，剛而居於巽體之上，可信其煉己有威如矣。煉己威如，嚴之於初，自能吉之於終。此煉己而有始有終者也。</p><p>子書雲：“煉己不熟，還丹不結。”還丹頭一步功夫，先要煉己，煉己煉到無己時，虛室生白，先天之氣，自虛無中來，凝結而成黍米之珠，其光通天徹地，一切魍魎邪魔，焉得而近之？煉己之功豈小焉哉!</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
